const topDebtors = `-- name: TopDebtors :many
SELECT id, user_id, name, normalized_name, phone, normalized_phone, country, type, status, total_owed, total_paid, credit_limit, last_activity, notes, tags, created_at, updated_at, customer_number, assigned_to, credit_limit_approved_by
FROM customers
WHERE user_id = $1
  AND total_owed > 0
ORDER BY total_owed DESC
LIMIT $2
`

type TopDebtorsParams struct {
	UserID uuid.UUID `db:"user_id" json:"user_id"`
	Limit  int32     `db:"limit" json:"limit"`
}

func (q *Queries) TopDebtors(ctx context.Context, arg TopDebtorsParams) ([]Customer, error) {
	rows, err := q.db.Query(ctx, topDebtors, arg.UserID, arg.Limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Customer{}
	for rows.Next() {
		var i Customer
		if err := rows.Scan(
			&i.ID,
			&i.UserID,
			&i.Name,
			&i.NormalizedName,
			&i.Phone,
			&i.NormalizedPhone,
			&i.Country,
			&i.Type,
			&i.Status,
			&i.TotalOwed,
			&i.TotalPaid,
			&i.CreditLimit,
			&i.LastActivity,
			&i.Notes,
			&i.Tags,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.CustomerNumber,
			&i.AssignedTo,
			&i.CreditLimitApprovedBy,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

